<script setup>
import { computed } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { products, merchants } from '../data'; import { Plus, Star, MapPin } from 'lucide-vue-next';
const route=useRoute(), router=useRouter(); const keyword=computed(()=>route.query.keyword||''); const filtered=computed(()=>products.filter(p=>(!keyword.value || (p.name+p.desc+p.nutrition).includes(keyword.value)))); const merchantFor=id=>merchants.find(m=>m.id===id)
</script>
<template><div class="explore-toolbar"><div><h2>按你的节奏挑选</h2><p>{{keyword ? `“${keyword}” 的搜索结果` : '今天想吃点什么？我们为你准备好了。'}}</p></div><div class="filters"><button class="filter active">全部</button><button class="filter">低卡</button><button class="filter">高蛋白</button><button class="filter">素食</button></div></div><div class="product-grid"><article v-for="p in filtered" :key="p.id" class="product-card"><div class="product-img">{{p.emoji}}<span class="nutrition">{{p.nutrition}}</span></div><div class="product-body"><div class="product-merchant"><span>{{merchantFor(p.merchantId)?.name}}</span><span>★ {{merchantFor(p.merchantId)?.rating}}</span></div><h3>{{p.name}}</h3><p>{{p.desc}}</p><div class="product-bottom"><b>¥{{p.price}}</b><button class="icon-btn" title="加入购物车"><Plus :size="18"/></button></div></div></article></div><div v-if="!filtered.length" class="empty">没有找到匹配的菜品，换个关键词试试。</div></template>
